#!/usr/bin/env bash
# =============================================================================
# PARROTO - seed the free public "TOEIC cơ bản – Cụm từ thông dụng" deck into vocabulary_db.
# Runs after 02-seed-b2-vocab.sh on the FIRST start of an empty volume.
# The SQL is generated by scripts/gen-toeic-seed.py and is idempotent.
# =============================================================================
set -euo pipefail
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname vocabulary_db \
  -f /docker-entrypoint-initdb.d/seed/007_seed_toeic_basic_deck.sql
